local VERSION='9.0.0'
local episodeCosts, completeness, denials = {}, {}, {}
local function uid(p)return('%s-%s-%04d'):format(p,os.time(),math.random(0,9999))end
exports('BuildAdaptiveEpisodeCostV9',function(patientCid,episodeId,charges)local total=0;local byDepartment={};for _,c in ipairs(type(charges)=='table'and charges or{})do local amount=tonumber(c.amount)or 0;total=total+amount;local d=tostring(c.department or'other');byDepartment[d]=(byDepartment[d]or 0)+amount end;local item={id=uid('COST'),patientCid=patientCid,episodeId=episodeId,total=math.floor(total*100)/100,byDepartment=byDepartment,charges=#(charges or{}),createdAt=os.time()};episodeCosts[item.id]=item;return true,item end)
exports('ValidateCodingCompletenessV9',function(claim)local required={'diagnosis','procedure','provider','dateOfService','medicalNecessity'};local missing={};for _,key in ipairs(required)do if not claim or claim[key]==nil or claim[key]==''then missing[#missing+1]=key end end;local item={id=uid('CODE'),complete=#missing==0,missing=missing,score=math.floor((#required-#missing)/#required*100),createdAt=os.time()};completeness[item.id]=item;return item.complete,item end)
exports('PredictDenialRiskV9',function(claim)local risk=0;if not claim or not claim.authorization then risk=risk+30 end;if not claim or not claim.medicalNecessity then risk=risk+25 end;if claim and claim.codingScore and claim.codingScore<80 then risk=risk+25 end;if claim and claim.lateFiling then risk=risk+30 end;local item={id=uid('DENIAL'),risk=math.min(100,risk),level=risk>=70 and'high'or risk>=40 and'moderate'or'low',createdAt=os.time()};denials[item.id]=item;return item end)
exports('GetV9BillingBoard',function()return{version=VERSION,episodeCosts=episodeCosts,completeness=completeness,denials=denials,generatedAt=os.time()}end)
CreateThread(function()Wait(6700);pcall(function()exports['dpn-medical-core']:RegisterModule('dpn-medical-billing-plus',VERSION,{'episode_costing','coding_completeness','denial_prediction','revenue_integrity'})end);print('[dpn-medical-billing-plus] v9 episode costing and denial prevention active')end)
